--
-- Table structure for table `visitjeju`
--

DROP TABLE IF EXISTS `visitjeju`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `visitjeju` (
  `contentsid` varchar(30) NOT NULL COMMENT '@SelectWhere,@CountWhere,@UpdateWhere,@DeleteWhere',
  `measure_position_id` bigint DEFAULT NULL COMMENT '측정위치ID',
  `contentscd` varchar(20) NOT NULL COMMENT '@SelectWhere,@CountWhere,@UpdateWhere,@DeleteWhere',
  `title` varchar(50) NOT NULL COMMENT '@SelectWhereLike,@UpdateSet',
  `address` varchar(255) DEFAULT NULL COMMENT '@SelectWhereLike,@UpdateSet',
  `roadaddress` varchar(255) DEFAULT NULL COMMENT '@SelectWhereLike,@UpdateSet',
  `tag` varchar(200) DEFAULT NULL COMMENT '@SelectWhereLike,@UpdateSet',
  `introduction` varchar(500) DEFAULT NULL COMMENT '@UpdateSet',
  `latitude` decimal(18,15) DEFAULT NULL COMMENT '@UpdateSet',
  `longitude` decimal(18,15) DEFAULT NULL COMMENT '@UpdateSet',
  `postcode` int DEFAULT NULL COMMENT '@SelectWhere,@UpdateSet',
  `phoneno` varchar(40) DEFAULT NULL COMMENT '전화번호',
  `url` varchar(255) DEFAULT NULL COMMENT '대표URL',
  `fee` varchar(200) DEFAULT NULL COMMENT '요금정보',
  `parking` char(1) DEFAULT NULL COMMENT '주차시설',
  `use_time` varchar(200) DEFAULT NULL COMMENT '이용시간',
  `detail_info` varchar(500) DEFAULT NULL COMMENT '상세정보',
  `image1_id` bigint DEFAULT NULL COMMENT '이미지1',
  `image2_id` bigint DEFAULT NULL COMMENT '이미지2',
  `kakao_code` varchar(20) DEFAULT NULL COMMENT 'kakao_code',
  `has_visitor_data` char(1) DEFAULT NULL COMMENT 'has_visitor_data',
  PRIMARY KEY (`contentsid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AUTOGEN-Visitjeju:net.jw.twin.db.visitjeju';
