DROP TABLE IF EXISTS `visitjeju_image`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `visitjeju_image` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '@AutoIncrease,@SelectWhere,@CountWhere,@UpdateWhere,@DeleteWhere',
  `file_item_id` bigint DEFAULT NULL COMMENT '@UpdateSet',
  `latitude` decimal(18,15) DEFAULT NULL COMMENT '@SelectWhere,@UpdateSet',
  `longitude` decimal(18,15) DEFAULT NULL COMMENT '@SelectWhere,@UpdateSet',
